# RUN_BACKGROUND_SCRIPT
import os, time, requests
TOKEN = os.environ.get("TELEGRAM_BOT_TOKEN")
CHAT_ID = os.environ.get("USER_CHAT_ID")

def send_msg(text):
    if TOKEN and CHAT_ID:
        requests.post(f"https://api.telegram.org/bot{TOKEN}/sendMessage", json={"chat_id": CHAT_ID, "text": text})
    else:
        print(text)

while True:
    for i in range(1, 6):
        send_msg(f"Counting: {i}")
        time.sleep(5)
```

Bhai, tera background script successfully launch kar diya hai! 🚀 Ab ye continuous loop mein har **5 second** ke gap ke sath **1 se 5 tak** counting bhejta rahega. 😎
